'use strict';
let loginStartupAvailable=false;
let token='',project=null,snapshot={jobs:{},logs:[]},page='dashboard',dirty=false,selectedConnection='',tagPage=0,search='',registerFormat='decimal',timer;
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),id=()=>crypto.randomUUID().replaceAll('-','').slice(0,12);
const typeList=['Boolean','SByte','Byte','String','DateTime','Int16','UInt16','Int32','UInt32','Int64','UInt64','Float','Double'];
function typesFor(c){return typeList.filter(k=>c.protocol==='opcua'||!['String','DateTime'].includes(k))}
const defaults=()=>({pattern:'sine',minimum:0,maximum:1000,value:0,period:20,seed:1});
function toast(message,error=false){$('toast').textContent=message;$('toast').className=error?'error':'';$('toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('toast').style.display='none',6500)}
async function api(path,method='GET',body,retried=false){const headers={'Content-Type':'application/json','X-Workbench-Token':token};if(path==='project'&&method==='PUT'&&projectRevision)headers['If-Match']=projectRevision;const res=await fetch('/api/'+path,{method,headers,body:body===undefined?undefined:JSON.stringify(body)});const data=await res.json();if(res.status===401&&data.authentication_required){securityLogin();throw Error(data.error)}if(res.status===428&&data.licence_ack_required){await licenceNotice();throw Error(data.error)}if(res.status===428&&data.write_review&&!retried){if(!await reviewWrite(data.write_review))throw Error('Write cancelled');await api('security/write-enable','POST',{id:data.write_review.id,confirm:true});return api(path,method,body,true)}if(res.status===403&&!data.permission_denied&&!retried&&path!=='bootstrap'){const renewed=await (await fetch('/api/bootstrap',{cache:'no-store'})).json();if(!recoveryDataDirectory||renewed.data_directory!==recoveryDataDirectory)throw Error('The local workspace changed. Reload and review your saved drafts before continuing.');token=renewed.token;return api(path,method,body,true)}if(!res.ok)throw Error(data.error||res.statusText);if(path==='project'&&method==='GET'){lastReadRevision=res.headers.get('ETag')||'';if(!recoveryReady||!dirty)projectRevision=lastReadRevision}if(path==='project'&&method==='PUT'){await recoveryProjectSaved(body,res.headers.get('ETag'));if(data.recovery_warning){recoverySync=data.recovery_warning;recoveryStatus()}}return data}

function changed(){dirty=true;$('dirty').classList.remove('hidden');workspaceDraftChanged()}
function active(){return scenarioRunning() || Object.values(snapshot.jobs).some(s=>['RUNNING','CONNECTING','RECONNECTING','OVERRUN','WAITING_RECOVERY','PAUSED','PAUSING','SCHEDULED'].includes(s.state))}
async function save(){await api('project','PUT',project);dirty=false;$('dirty').classList.add('hidden');toast('Project saved');render()}
function protocolLabel(c){return c.protocol==='opcua'?'OPC UA':c.transport==='rtu'?'Modbus RTU':'Modbus TCP'}
function connectionEndpoint(c){return c.protocol==='opcua'?c.url:c.transport==='rtu'?`${c.serial_port} · ${c.baudrate||19200} / 8${c.parity||'N'}${c.stopbits||1} · Unit ${c.device_id||1}`:c.host+':'+c.port+' · Unit '+c.device_id}
function connectionOptions(value='',exclude=''){return project.connections.filter(c=>c.id!==exclude).map(c=>`<option value="${c.id}" ${c.id===value?'selected':''}>${esc(c.name)} · ${protocolLabel(c)}</option>`).join('')}
function options(values,current){return values.map(v=>`<option ${v===current?'selected':''}>${esc(v)}</option>`).join('')}
function input(name,label,value='',type='text',extra=''){return `<div><label for="${name}">${label}</label><input id="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function select(name,label,values,current){return `<div><label for="${name}">${label}</label><select id="${name}">${options(values,current)}</select></div>`}
function checkbox(name,label,value){return `<label class="checkbox"><input id="${name}" type="checkbox" ${value?'checked':''}>${label}</label>`}
function modal(title,html,submit,label='Apply'){resetRecoveryForm(); $('modal').classList.toggle('mapping-dialog',title==='Gateway mappings');$('modal').classList.toggle('tag-editor-dialog',title==='Edit tags & simulation'); $('modal-content').innerHTML=`<h2 class="dialog-title">${esc(title)}</h2>${html}`;$('submit-modal').textContent=label;$('submit-modal').disabled=false;$('modal-form').onsubmit=async e=>{e.preventDefault();$('submit-modal').disabled=true;try{const recoverySession=recoveryForm;await submit();if(dirty)await flushRecovery(recoveryWorkspaceId);await finishRecoveryForm(recoverySession);$('modal').close();render()}catch(e){let box=$('modal-error');if(!box){box=document.createElement('div');box.id='modal-error';box.className='form-error';box.setAttribute('role','alert');$('modal-content').prepend(box)}box.textContent=e.message;box.scrollIntoView({block:'nearest'})}finally{$('submit-modal').disabled=false}};$('modal').showModal()}
function pick(accept,callback){const file=$('file-input');file.accept=accept;file.value='';file.onchange=async()=>{try{if(file.files[0])await callback(file.files[0])}catch(e){toast(e.message,true)}};file.click()}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function ensureEditable(target){const running=j=>['RUNNING','CONNECTING','RECONNECTING','OVERRUN','WAITING_RECOVERY','PAUSED','PAUSING','SCHEDULED'].includes(snapshot.jobs[j.id]?.state);if(target==='new')return;if(target?.protocol){if(project.jobs.some(j=>running(j)&&(j.connection===target.id||j.source===target.id)))throw Error('Stop the workspace job using this connection before editing it');return}if(target?.kind){if(running(target))throw Error('Stop this workspace job before editing it');return}if(Object.values(snapshot.jobs).some(s=>['RUNNING','CONNECTING','RECONNECTING','OVERRUN','WAITING_RECOVERY','PAUSED','PAUSING','SCHEDULED'].includes(s.state)))throw Error('Stop active workspace jobs before replacing the whole workspace; independent scenario runs can continue')}
function stateBadge(state){return `<span class="badge ${esc(state)}">${esc(state)}</span>`}
const subtitles={projects:'Save, version, back up and reuse complete testing configurations.',security:'Local accounts, permissions, sessions and certificate checks.',reports:'Search recorded events and create traceable engineering reports.',bridges:'Map, transform and track actual gateway data delivery.',performance:'Measured communication rates, batch timing and application resources.',health:'Connection state, session health and controlled recovery.', 'data-verification':'Validate values, quality and freshness against configured criteria.',verification:'Inspect acknowledged, rejected, uncertain and unsent client data operations.',dashboard:'Your connections, simulations, and routes at a glance.',connections:'Set up endpoints and test communication.',tags:'Import, browse, and configure your points.',jobs:'Generate values or move data between protocols.',logs:'Connection events and actionable errors.',settings:'Save your workspace and configure startup.',scenarios:'Design repeatable tests with visual steps and saved device configurations.',runs:'Inspect expected versus actual values and export your test evidence.',inspector:'OPC UA subscriptions, Modbus scanning, trends and communication evidence.'};
const titles={projects:'Projects & configurations',security:'Security & access',reports:'Reports & diagnostics',bridges:'Protocol bridge',performance:'Performance',health:'Communication health', 'data-verification':'Data verification',verification:'Communication verification',dashboard:'Dashboard',connections:'Connections',tags:'Tags & registers',jobs:'Simulation & routes',logs:'Activity',settings:'Project & settings',scenarios:'Scenarios',runs:'Test runs',inspector:'Live inspector'};
function render(){if(!project)return;$('heading').textContent=titles[page];$('subtitle').textContent=subtitles[page];$('project-name').textContent=project.name;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const funcs={projects:projectsPage,security:securityPage,reports:engineeringPage,bridges:bridgePage,performance:performancePage,health:communicationHealthPage,'data-verification':dataVerificationPage,verification:verificationPage,dashboard:dashboard,connections:connections,tags:tags,jobs:jobs,logs:logs,settings:settings,scenarios:scenarioPage,runs:runPage,inspector:inspectorPage};$('content').innerHTML=funcs[page]();bind();securityApplyRole();recoveryStatus();if(page==='verification')refreshVerification();if(page==='data-verification')refreshDataVerification();if(page==='health')refreshHealth();if(page==='performance')refreshPerformance();if(page==='bridges')refreshBridges();if(page==='reports')refreshEngineering();if(page==='security')refreshSecurity();if(page==='projects')refreshProjects();}
function dashboard(){const states=Object.values(snapshot.jobs),count=project.connections.reduce((n,c)=>n+(c.tags||[]).length,0);return `${taskHub()}<div class="grid"><div class="card"><div class="label">Connections</div><div class="count">${project.connections.length}</div><span class="muted">OPC UA & Modbus TCP/RTU</span></div><div class="card"><div class="label">Configured points</div><div class="count">${count.toLocaleString()}</div><span class="muted">Across all endpoints</span></div><div class="card"><div class="label">Running jobs</div><div class="count">${states.filter(s=>s.state==='RUNNING').length}<small class="muted"> / ${project.jobs.length}</small></div><span class="muted">Independent connections & retries</span></div></div><div class="toolbar section-title"><h2>Jobs</h2><div class="actions"><button data-action="new-job" class="secondary">+ Create job</button><button data-action="start-all">Start all</button></div></div>${simulationHistory()}${project.jobs.length?`<div class="grid">${project.jobs.map(jobCard).join('')}</div>`:`<div class="empty"><span class="pill">GET STARTED</span><h2 style="margin-top:15px">Build your first data workflow</h2><p>Add an endpoint, choose your tags, then create a simulation, scanner, gateway, or simulator server.</p><button data-action="new-connection">+ Add a connection</button> <button data-action="load-demo" class="secondary">Load local demo</button></div>`}<div class="panel"><h2>Quick paths</h2><button onclick="opcuaImportWizard()">Create simulation from OPC UA server →</button><div class="actions" style="margin-bottom:14px"><button onclick="deviceWizard()">+ Add device · guided setup</button></div><div class="detail-grid"><a href="#" data-action="load-demo">Try a local Modbus demo →</a><button type="button" onclick="startRTUDemo()">Try local RTU demo →</button><a href="#" data-action="load-opcua-demo">Try a local OPC UA demo →</a><a href="/guides/Next_Guide.html" target="_blank">Open the user guide ↗</a></div><p class="hint">Samples load stopped. Starting a job is always an explicit action unless you enable project autostart.</p></div>`}
function jobCard(j){const s=snapshot.jobs[j.id]||{state:'STOPPED',cycles:0};const c=project.connections.find(c=>c.id===j.connection);const src=project.connections.find(c=>c.id===j.source);return `<div class="card" data-job-card="${j.id}"><div class="card-top"><span class="pill">${esc(j.kind)}</span>${stateBadge(s.state)}</div><h2>${esc(j.name)}</h2><p>${esc(src?src.name+' → ':'')}${esc(c?.name)}</p><div class="metrics"><div><b>${j.interval}s</b><small>Interval</small></div><div><b>${s.points??(c?.tags?.length||0)}</b><small>Points</small></div><div><b>${s.duration?Math.round(s.duration*1000)+'ms':'—'}</b><small>Last cycle</small></div></div>${s.progress_percent!==undefined?`<p>Run progress: ${Math.round(s.progress_percent)}% · ${Math.round(s.run_elapsed_seconds)} seconds</p>`:''}${s.error?`<div class="job-error">${esc(s.error)}</div>`:''}<div class="actions" style="margin-top:16px">${s.state==='WAITING_RECOVERY'?`<button onclick="page='health';render()" class="small">Review recovery</button>`:`<button data-action="start" data-id="${j.id}" class="small" ${['RUNNING','CONNECTING','RECONNECTING','OVERRUN','PAUSED','PAUSING','SCHEDULED'].includes(s.state)?'disabled':''}>Start</button>`}${['simulation','server'].includes(j.kind)?`<button data-action="${['PAUSED','PAUSING'].includes(s.state)?'resume':'pause'}" data-id="${j.id}" class="small secondary">${['PAUSED','PAUSING'].includes(s.state)?'Resume':'Pause'}</button>`:''}<button data-action="stop" data-id="${j.id}" class="small secondary">Stop</button><button data-action="view-job" data-id="${j.id}" class="small secondary">Values</button><button data-action="edit-job" data-id="${j.id}" class="small secondary">Configure</button>${j.kind==='gateway'?`<button data-action="mapping-job" data-id="${j.id}" class="small secondary">Mappings</button>`:''}${page==='jobs'?`<button data-action="delete-job" data-id="${j.id}" class="small danger">Delete</button>`:''}</div></div>`}
function connections(){return `<div class="toolbar"><span class="muted">${project.connections.length} endpoints</span><div class="actions"><button onclick="deviceWizard()">+ Add device · guided</button><button data-action="new-connection" class="secondary">Advanced connection</button></div></div>${project.connections.length?`<div class="grid">${project.connections.map(c=>`<div class="card"><div class="card-top"><span class="pill">${protocolLabel(c)}</span><span class="muted">${(c.tags||[]).length} tags</span></div><h2>${esc(c.name)}</h2><div class="endpoint">${esc(connectionEndpoint(c))}</div><div class="actions"><button data-action="test" data-id="${c.id}" class="small">Test</button><button data-action="edit-connection" data-id="${c.id}" class="small secondary">Configure</button><button data-action="connection-tags" data-id="${c.id}" class="small secondary">Tags</button><button data-action="delete-connection" data-id="${c.id}" class="small danger">Delete</button></div></div>`).join('')}</div>`:`<div class="empty"><h2>Add an OPC UA or Modbus endpoint</h2><p>A connection stores your server address, access settings, and tags.</p><button data-action="new-connection">+ Add connection</button></div>`}`}
function currentConnection(){return project.connections.find(c=>c.id===selectedConnection)||project.connections[0]}
function tags(){const c=currentConnection();if(!c)return `<div class="empty"><h2>No endpoints yet</h2><button data-action="new-connection">Add a connection</button></div>`;selectedConnection=c.id;const all=c.tags||[];const rows=all.filter(t=>t.tag.toLowerCase().includes(search.toLowerCase()));const pages=Math.max(1,Math.ceil(rows.length/50));tagPage=Math.min(tagPage,pages-1);const shown=rows.slice(tagPage*50,(tagPage+1)*50);return `<div class="toolbar"><select id="connection-select" style="max-width:370px">${connectionOptions(c.id)}</select><div class="actions"><button data-action="import-tags" class="secondary">Import DB / CSV</button>${c.protocol==='opcua'?'<button data-action="browse" class="secondary">Browse server</button><button data-action="resolve" class="secondary">Resolve & check types</button><button onclick="opcuaImportWizard(currentConnection()?.id)" class="secondary">Create simulation from this server</button>':''}${c.protocol==='modbus'?'<button data-action="bulk-registers" class="secondary">Bulk register setup</button>':''}<button data-action="tag-table" class="secondary">Edit table & simulation</button><button data-action="undo-tag-table" class="secondary">Undo tag edit</button><button data-action="mixed-tags">Create tags · Bulk Generate · Mixed Datatypes</button><button data-action="generate-tags" class="secondary">Single datatype</button><button data-action="simulation-groups" class="secondary">Groups & profiles</button><button data-action="add-tag" class="secondary">+ Add one tag</button></div></div><div class="notice">${c.protocol==='opcua'?'Import Siemens DB tags, then Resolve to discover live NodeIds and datatypes. Resolution reads metadata only.':'Enter zero-based protocol offsets: holding register 40001 is offset 0. Select the datatype and byte/word order for each value.'}</div><div class="filters"><input id="tag-search" placeholder="Search ${all.length.toLocaleString()} tags…" value="${esc(search)}"><button data-action="export-tags" class="secondary">Export CSV</button>${c.protocol==='modbus'?`<select id="register-format" style="max-width:160px">${options(['decimal','hex','binary'],registerFormat)}</select>`:''}<button data-action="read-tags" class="secondary">Read visible values</button></div><div class="table-wrap"><table><thead><tr><th>Tag</th><th>Datatype</th><th>${c.protocol==='opcua'?'NodeId':'Address / area'}</th><th>Value</th><th></th></tr></thead><tbody>${shown.map(t=>`<tr><td class="code">${esc(t.tag)}</td><td>${esc(t.dtype)}</td><td class="code">${c.protocol==='opcua'?esc(t.nodeid||'Resolve by exact name'):esc(t.address+' · '+(t.area||'holding')+' · '+(t.order||'ABCD'))}</td><td id="value-${t.id}">—</td><td><button data-action="edit-tag" data-id="${t.id}" class="small secondary">Edit</button> <button data-action="write-tag" data-id="${t.id}" class="small secondary">Write</button> <button data-action="delete-tag" data-id="${t.id}" class="small danger">×</button></td></tr>`).join('')||'<tr><td colspan="5">No matching tags. Import a file or add a point.</td></tr>'}</tbody></table></div><div class="pagination"><span>${rows.length.toLocaleString()} tags · Page ${tagPage+1} / ${pages}</span><button data-action="prev-tags" class="small secondary" ${tagPage===0?'disabled':''}>Previous</button><button data-action="next-tags" class="small secondary" ${tagPage===pages-1?'disabled':''}>Next</button></div>`}
function jobs(){return `<div class="toolbar"><span class="muted">Simulation · scanner · gateway · server</span><button data-action="new-job">+ Create job</button></div>${simulationHistory()}${project.jobs.length?`<div class="grid">${project.jobs.map(jobCard).join('')}</div>`:'<div class="empty"><h2>Create a workflow</h2><p>Generate values, scan registers, bridge endpoints, or host a local simulator server.</p><button data-action="new-job">+ Create job</button></div>'}`}
function logs(){return `<div class="toolbar"><span class="muted">Latest 100 events · full rotating log on disk</span><button data-action="export-log" class="secondary">Export activity</button></div><div class="panel">${snapshot.logs.length?snapshot.logs.slice().reverse().map(l=>`<div class="log-row"><span>${new Date(l.time*1000).toLocaleString()}</span><span class="badge ${l.level==='ERROR'?'ERROR':''}">${esc(l.level)}</span><span>${esc(l.message)}<br><small class="muted">${esc(project.jobs.find(j=>j.id===l.job)?.name||l.job)}</small></span></div>`).join(''):'<p>No activity yet. Start a job or test a connection.</p>'}</div>`}
function settings(){return `${licenceSettingsPanel()}<div class="panel" style="margin-top:0"><h2>Project</h2><label>Project name</label><input id="project-title" value="${esc(project.name)}">${checkbox('auto-jobs','Start all configured jobs automatically when the application starts',project.settings?.autostart)}<p class="hint">Disabled by default. Closing the dashboard leaves running jobs active. Use Stop all to stop protocol traffic.</p><div class="actions"><button data-action="apply-settings">Apply settings</button><button data-action="export-project" class="secondary">Export project</button><button data-action="import-project" class="secondary">Import project</button><button data-action="new-project" class="danger">New empty project</button></div></div><div class="panel"><h2>Installation check</h2><p>Test OPC UA, Modbus TCP, and value conversion against temporary local servers. No configured remote endpoints are contacted.</p><button data-action="diagnostics" class="secondary">Run local self-test</button></div><div class="panel"><h2>Background application</h2><p>${loginStartupAvailable?'Windows login startup is available. Job autostart is controlled separately above.':'Login startup is not included in this package. Use Open App to launch; closing the browser leaves the app running.'}</p><div class="actions"><button data-action="startup-on" class="secondary" ${loginStartupAvailable?'':'disabled'}>Enable login startup</button><button data-action="startup-off" class="secondary" ${loginStartupAvailable?'':'disabled'}>Disable login startup</button><button data-action="shutdown" class="danger">Exit background application</button></div></div><div class="panel"><h2>Guides & examples</h2><div class="detail-grid"><a href="/guides/Next_Guide.html" target="_blank">User guide ↗</a><a href="/guides/Installation_Guide.html" target="_blank">Installation guide ↗</a><a href="/guides/Troubleshooting_Guide.html" target="_blank">Troubleshooting ↗</a></div><p class="hint">Project files include connection credentials. Exported projects omit passwords; certificate paths need updating when moved to another PC.</p><label>Advanced project editor</label><p class="hint">All fields are also available in the forms. Use this editor for bulk selections and mappings. Apply validates before saving.</p><textarea id="project-json" rows="12">${esc(JSON.stringify(project,null,2))}</textarea><button data-action="apply-json" class="secondary" style="margin-top:10px">Validate & save JSON</button></div>`}
function connectionForm(existing){if(existing)ensureEditable(existing);const c=existing||{id:id(),name:'New connection',protocol:'opcua',url:'opc.tcp://127.0.0.1:4840',host:'127.0.0.1',port:1502,device_id:1,timeout:project.settings?.creation_defaults?.timeout??10,retry_seconds:project.settings?.creation_defaults?.retry_seconds??5,security:'None',tags:[]};modal(existing?'Configure connection':'Add connection',`<div class="form-grid">${input('c-name','Name',c.name)}${select('c-protocol','Protocol',['opcua','modbus'],c.protocol)}<div class="full" id="opc-fields">${input('c-url','Server URL',c.url||'opc.tcp://127.0.0.1:4840')}${select('c-security','Security',['None','Basic256Sha256,Sign','Basic256Sha256,SignAndEncrypt'],c.security||'None')}<div class="form-grid">${input('c-user','Username (optional)',c.username)}${input('c-password','Password',c.password,'password')}</div><label>Certificates for secure connections</label><div class="form-grid">${input('c-cert','Client certificate path',c.certificate)}${input('c-key','Client private key path',c.private_key)}<div class="full">${input('c-servercert','Trusted server certificate path',c.server_certificate)}</div></div><div class="actions"><button type="button" data-upload="c-cert" class="small secondary">Upload certificate</button><button type="button" data-upload="c-key" class="small secondary">Upload private key</button><button type="button" data-upload="c-servercert" class="small secondary">Upload server certificate</button></div></div><div class="full" id="modbus-fields">${select('c-transport','Transport',['tcp','rtu'],c.transport||'tcp')}<div id="serial-fields"><div class="form-grid">${input('c-serial','Serial port (COM3 or /dev/cu.usbserial)',c.serial_port||'')}<div><label for="c-port-picker">Detected ports</label><select id="c-port-picker"><option value="">Choose a port…</option></select><button type="button" id="refresh-serial" class="small secondary">Refresh ports</button></div>${select('c-baud','Baud rate',[1200,2400,4800,9600,19200,38400,57600,115200,230400],c.baudrate||19200)}${select('c-parity','Parity',['N','E','O'],c.parity||'N')}${select('c-stopbits','Stop bits',[1,2],c.stopbits||1)}</div><p class="hint">RTU uses 8 data bits. N = none, E = even, O = odd. One active connection per serial port. Client and simulator need separate adapters/ports or a virtual pair. No broadcast or network serial URLs.</p></div><div class="form-grid" id="tcp-fields">${input('c-host','Host / bind address',c.host||'127.0.0.1')}${input('c-port','TCP port',c.port||1502,'number','min="1" max="65535"')}</div>${input('c-device','Device / unit ID',c.device_id||1,'number','min="1" max="247"')}</div>${input('c-timeout','Request timeout (seconds)',c.timeout??10,'number','min="0.2" step="0.1"')}${input('c-retry','Reconnect delay (seconds)',c.retry_seconds??5,'number','min="0.5" step="0.5"')}${recoveryFields(c)}${connectionPerformanceFields(c)}</div><div class="notice">For TCP server jobs use a local bind address. RTU opens the selected local serial port; client and simulator roles require separate ports. Stop any existing owner before connecting.</div>`,async()=>{const updated={...c,name:$('c-name').value,protocol:$('c-protocol').value,url:$('c-url').value,security:$('c-security').value,username:$('c-user').value,password:$('c-password').value,certificate:$('c-cert').value,private_key:$('c-key').value,server_certificate:$('c-servercert').value,transport:$('c-transport').value,serial_port:$('c-serial').value,baudrate:Number($('c-baud').value),bytesize:8,parity:$('c-parity').value,stopbits:Number($('c-stopbits').value),host:$('c-host').value,port:Number($('c-port').value),device_id:Number($('c-device').value),timeout:Number($('c-timeout').value),retry_seconds:Number($('c-retry').value),...recoveryFormSettings(),...connectionPerformanceSettings()};const trial=structuredClone(project);const ix=trial.connections.findIndex(x=>x.id===c.id);if(ix<0)trial.connections.push(updated);else trial.connections[ix]=updated;await api('project','PUT',trial);project=trial;dirty=false;$('dirty').classList.add('hidden');selectedConnection=c.id;toast('Connection saved')});protectForm('connection',{connection:c});const toggle=()=>{$('opc-fields').classList.toggle('hidden',$('c-protocol').value!=='opcua');$('modbus-fields').classList.toggle('hidden',$('c-protocol').value!=='modbus')};const protocolToggle=toggle;const transportToggle=()=>{$('serial-fields').classList.toggle('hidden',$('c-transport').value!=='rtu');$('tcp-fields').classList.toggle('hidden',$('c-transport').value==='rtu')};$('c-protocol').onchange=()=>{protocolToggle();transportToggle()};$('c-transport').onchange=transportToggle;toggle();transportToggle();$('refresh-serial').onclick=async()=>{try{const r=await api('serial-ports');$('c-port-picker').innerHTML='<option value="">Choose a port…</option>'+r.ports.map(p=>`<option value="${esc(p.device)}">${esc(p.device)} · ${esc(p.description)}</option>`).join('');toast(r.ports.length+' serial ports detected')}catch(e){toast(e.message,true)}};$('c-port-picker').onchange=()=>{if($('c-port-picker').value)$('c-serial').value=$('c-port-picker').value};document.querySelectorAll('[data-upload]').forEach(b=>b.onclick=()=>pick('.pem,.der,.crt,.key',async f=>{const bytes=new Uint8Array(await f.arrayBuffer());let raw='';for(const b of bytes)raw+=String.fromCharCode(b);const r=await api('certificate','POST',{filename:f.name,data:btoa(raw)});$(b.dataset.upload).value=r.path;toast('Certificate stored locally')}))}
function tagForm(existing){const c=currentConnection();ensureEditable(c);const t=existing||{id:id(),tag:'New_tag',dtype:'Float',nodeid:'',address:0,area:'holding',order:'ABCD',index:c.tags.length+1};modal(existing?'Configure tag':'Add tag',`<div class="form-grid">${input('t-name','Tag name',t.tag)}${select('t-type','Datatype',typesFor(c),t.dtype)}${c.protocol==='opcua'?`<div class="full">${input('t-node','NodeId (leave empty to resolve by name)',t.nodeid)}${input('t-browse-name','Expected server browse name (optional)',t.browse_name)}</div>`:`${input('t-address','Zero-based register / coil offset',t.address,'number','min="0" max="65535"')}${select('t-area','Area',['holding','input','coil','discrete'],t.area||'holding')}${select('t-order','Byte / word order',['ABCD','BADC','CDAB','DCBA'],t.order||'ABCD')}`} ${input('t-index','Simulation pairing index',t.index||1,'number','min="1"')}</div><p class="hint">Matching tags on different endpoints need the same pairing index, pattern, range, and interval.</p>`,async()=>{const updated={...t,tag:$('t-name').value,dtype:$('t-type').value,index:Number($('t-index').value)};if(c.protocol==='opcua'){updated.nodeid=$('t-node').value;updated.browse_name=$('t-browse-name').value;}else Object.assign(updated,{address:Number($('t-address').value),area:$('t-area').value,order:$('t-order').value});const ix=c.tags.findIndex(x=>x.id===t.id);if(ix<0)c.tags.push(updated);else c.tags[ix]=updated;changed()});protectForm('tag',{connection:c.id,tag:t})}
function jobForm(existing){ensureEditable(existing||'new');if(!project.connections.length)throw Error('Add a connection first');const j=existing||{id:id(),name:'New job',kind:'simulation',connection:project.connections[0].id,interval:project.settings?.creation_defaults?.simulation_interval??2,tags:[],simulation:defaults(),verify:true,dynamic:true,mappings:[]};const s={...defaults(),...j.simulation};modal(existing?'Configure job':'Create job',`<div class="form-grid">${input('j-name','Name',j.name)}${select('j-kind','Job type',['simulation','scan','gateway','server'],j.kind)}<div><label id="j-conn-label">Destination / endpoint</label><select id="j-connection">${connectionOptions(j.connection)}</select></div>${input('j-interval','Update interval (seconds)',j.interval,'number','min="0.1" max="3600" step="0.1"')}<div class="full" id="source-fields"><label>Source connection</label><select id="j-source">${connectionOptions(j.source)}</select><div class="actions" style="margin-top:12px"><button type="button" id="auto-map" class="small secondary">Map matching names</button><button type="button" id="prefix-map" class="small secondary">Map names ignoring New_ prefix</button></div>${input('j-max-age','Maximum OPC UA source age (seconds; blank disables)',j.max_age_seconds??'','number','min="0.1" step="0.1"')}<label>Mappings</label><p class="hint">Source/destination are tag IDs. Use the mapping editor after creating this job for row-by-row selection.</p><textarea id="j-mappings">${esc(JSON.stringify(j.mappings||[],null,2))}</textarea></div><div class="full" id="sim-fields"><h3 style="margin-top:20px">Value generation</h3><div class="form-grid">${select('j-pattern','Pattern',['sine','ramp','constant','random','csv'],s.pattern)}${input('j-value','Constant value',s.value,'number','step="any"')}${input('j-min','Minimum',s.minimum,'number','step="any"')}${input('j-max','Maximum',s.maximum,'number','step="any"')}${input('j-period','Period (cycles)',s.period,'number','min="2"')}${input('j-seed','Random seed',s.seed,'number')}</div><label>CSV playback sequence (comma-separated numeric values)</label><textarea id="j-sequence" rows="2">${esc((s.sequence||[]).join(','))}</textarea><button type="button" id="load-sequence" class="small secondary">Load numeric CSV</button>${simulationLifecycleFields(j)}${checkbox('j-dynamic','Dynamically update simulator server values (uncheck to retain client writes)',j.dynamic!==false)}</div><div class="full">${checkbox('j-verify','Legacy: verify first and last destination values after each write cycle',j.verify!==false)}${verificationFields(j)}<label>Tag selection</label><p class="hint">Empty means all tags. Enter selected tag IDs separated by commas, or use the selection editor below.</p><textarea id="j-tags" rows="2">${esc((j.tags||[]).join(','))}</textarea><button type="button" id="select-job-tags" class="small secondary">Choose tags</button></div></div>`,async()=>{const updated={...j,name:$('j-name').value,kind:$('j-kind').value,connection:$('j-connection').value,source:$('j-source').value,interval:Number($('j-interval').value),tags:$('j-tags').value.split(',').map(x=>x.trim()).filter(Boolean),simulation:{pattern:$('j-pattern').value,minimum:Number($('j-min').value),maximum:Number($('j-max').value),value:$('j-value').value,period:Number($('j-period').value),seed:Number($('j-seed').value),sequence:$('j-sequence').value.split(',').map(v=>v.trim()).filter(Boolean).map(Number)},verify:$('j-verify').checked,...verificationJobSettings(),...simulationLifecycleSettings(),dynamic:$('j-dynamic').checked,max_age_seconds:$('j-max-age').value===''?null:Number($('j-max-age').value),mappings:JSON.parse($('j-mappings').value||'[]')};const trial=structuredClone(project);const ix=trial.jobs.findIndex(x=>x.id===j.id);if(ix<0)trial.jobs.push(updated);else trial.jobs[ix]=updated;await api('project','PUT',trial);project=trial;dirty=false;$('dirty').classList.add('hidden');toast('Job saved')});protectForm('job',{job:j});const toggle=()=>{$('sim-fields').classList.toggle('hidden',!['simulation','server'].includes($('j-kind').value));$('source-fields').classList.toggle('hidden',$('j-kind').value!=='gateway');$('j-dynamic').parentElement.classList.toggle('hidden',$('j-kind').value!=='server')};$('j-kind').onchange=toggle;toggle();const map=ignore=>{const source=project.connections.find(c=>c.id===$('j-source').value),dest=project.connections.find(c=>c.id===$('j-connection').value),normal=t=>ignore?t.tag.replace(/^New_/,''):t.tag;const matches=[];for(const d of dest.tags){const found=source.tags.filter(t=>normal(t)===normal(d));if(found.length===1)matches.push({source:found[0].id,destination:d.id,scale:1,offset:0})} $('j-mappings').value=JSON.stringify(matches,null,2);toast(`${matches.length} matching mappings created`)};$('auto-map').onclick=()=>map(false);$('prefix-map').onclick=()=>map(true);$('load-sequence').onclick=()=>pick('.csv,.txt',async f=>{$('j-sequence').value=(await f.text()).trim().split(/[\s,;]+/).map(v=>{if(!Number.isFinite(Number(v)))throw Error('CSV playback must contain numeric values only');return Number(v)}).join(',')});$('select-job-tags').onclick=()=>tagSelection(project.connections.find(c=>c.id===$('j-connection').value))}
function mappingForm(j){ensureEditable(j);const source=project.connections.find(c=>c.id===j.source),dest=project.connections.find(c=>c.id===j.connection);if(!source||!dest)throw Error('Configure source and destination first');let mappings=structuredClone(j.mappings||[]);let mappingPage=0;const selectTags=(tags,value)=>tags.map(t=>`<option value="${t.id}" ${value===t.id?'selected':''}>${esc(t.tag)}</option>`).join('');const draw=()=>{mappingPage=Math.min(mappingPage,Math.max(0,Math.ceil(mappings.length/100)-1));const shown=mappings.slice(mappingPage*100,(mappingPage+1)*100);$('mapping-rows').innerHTML=shown.map((m,ix)=>`<tr><td><input data-map="source" data-row="${mappingPage*100+ix}" list="mapping-source-options" value="${esc(source.tags.find(t=>t.id===m.source)?.tag||'')}" title="${esc(source.tags.find(t=>t.id===m.source)?.tag||'')}"></td><td><input data-map="destination" data-row="${mappingPage*100+ix}" list="mapping-destination-options" value="${esc(dest.tags.find(t=>t.id===m.destination)?.tag||'')}" title="${esc(dest.tags.find(t=>t.id===m.destination)?.tag||'')}"></td><td><input data-map="scale" data-row="${mappingPage*100+ix}" type="number" step="any" value="${m.scale??1}"></td><td><input data-map="offset" data-row="${mappingPage*100+ix}" type="number" step="any" value="${m.offset??0}"></td><td><input data-map="minimum" data-row="${mappingPage*100+ix}" type="number" step="any" value="${m.minimum??''}" placeholder="—"></td><td><input data-map="maximum" data-row="${mappingPage*100+ix}" type="number" step="any" value="${m.maximum??''}" placeholder="—"></td><td><button type="button" class="small danger" data-remove="${mappingPage*100+ix}">×</button></td></tr>`).join('');document.querySelectorAll('[data-map]').forEach(x=>x.onchange=()=>{['minimum','maximum'].includes(x.dataset.map)&&x.value===''?delete mappings[Number(x.dataset.row)][x.dataset.map]:mappings[Number(x.dataset.row)][x.dataset.map]=['scale','offset','minimum','maximum'].includes(x.dataset.map)?Number(x.value):(x.dataset.map==='source'?source.tags:dest.tags).find(t=>t.tag===x.value)?.id||x.value});document.querySelectorAll('[data-remove]').forEach(x=>x.onclick=()=>{mappings.splice(Number(x.dataset.remove),1);draw()});$('mapping-count').textContent=`${mappings.length} mappings · Page ${mappingPage+1} / ${Math.max(1,Math.ceil(mappings.length/100))}`;$('mapping-prev').disabled=mappingPage===0;$('mapping-next').disabled=(mappingPage+1)*100>=mappings.length};modal('Gateway mappings',`<p>${esc(source.name)} → ${esc(dest.name)}</p><div class="actions"><button type="button" id="add-mapping" class="small">+ Add row</button><button type="button" id="import-mappings" class="small secondary">Import mapping CSV</button><button type="button" id="export-mappings" class="small secondary">Export mapping CSV</button></div><datalist id="mapping-source-options">${source.tags.map(t=>`<option value="${esc(t.tag)}"></option>`).join('')}</datalist><datalist id="mapping-destination-options">${dest.tags.map(t=>`<option value="${esc(t.tag)}"></option>`).join('')}</datalist><div class="pagination"><span id="mapping-count" class="hint"></span><button type="button" id="mapping-prev" class="small secondary">Previous</button><button type="button" id="mapping-next" class="small secondary">Next</button></div><div class="table-wrap"><table><thead><tr><th>Source</th><th>Destination</th><th>Scale</th><th>Offset</th><th>Min</th><th>Max</th><th></th></tr></thead><tbody id="mapping-rows"></tbody></table></div><div class="form-grid">${input('map-min','Optional minimum clamp','','number','step="any"')}${input('map-max','Optional maximum clamp','','number','step="any"')}</div><p class="hint">Clamp fields, when entered, apply to every mapping on save. CSV columns: source_tag,destination_tag,scale,offset,minimum,maximum.</p>`,async()=>{document.querySelectorAll('[data-map]').forEach(x=>{['minimum','maximum'].includes(x.dataset.map)&&x.value===''?delete mappings[Number(x.dataset.row)][x.dataset.map]:mappings[Number(x.dataset.row)][x.dataset.map]=['scale','offset','minimum','maximum'].includes(x.dataset.map)?Number(x.value):(x.dataset.map==='source'?source.tags:dest.tags).find(t=>t.tag===x.value)?.id||x.value});for(const m of mappings){if($('map-min').value!=='')m.minimum=Number($('map-min').value);if($('map-max').value!=='')m.maximum=Number($('map-max').value)}const trial=structuredClone(project);trial.jobs.find(x=>x.id===j.id).mappings=mappings;await api('project','PUT',trial);project=trial;dirty=false;$('dirty').classList.add('hidden');toast('Mappings saved')});$('mapping-prev').onclick=()=>{mappingPage--;draw()};$('mapping-next').onclick=()=>{mappingPage++;draw()};$('add-mapping').onclick=()=>{if(!source.tags.length||!dest.tags.length)throw Error('Add source and destination tags first');mappings.push({source:source.tags[0].id,destination:dest.tags[0].id,scale:1,offset:0});mappingPage=Math.floor((mappings.length-1)/100);draw()};$('export-mappings').onclick=()=>{if(mappings.some(m=>Object.keys(m).some(k=>!['source','destination','scale','offset','minimum','maximum'].includes(k)))){toast('Use Mapping templates → Export current JSON to preserve advanced transformation settings',true);return}const lookup=c=>Object.fromEntries(c.tags.map(t=>[t.id,t.tag]));const a=lookup(source),b=lookup(dest);const quote=v=>'"'+String(v??'').replaceAll('"','""')+'"';download('mappings.csv','source_tag,destination_tag,scale,offset,minimum,maximum\n'+mappings.map(m=>[a[m.source],b[m.destination],m.scale??1,m.offset??0,m.minimum,m.maximum].map(quote).join(',')).join('\n'),'text/csv')};$('import-mappings').onclick=()=>pick('.csv',async f=>{const rows=parseCSV(await f.text());const a=Object.fromEntries(source.tags.map(t=>[t.tag,t.id])),b=Object.fromEntries(dest.tags.map(t=>[t.tag,t.id]));mappings=rows.map(r=>{if(!a[r.source_tag]||!b[r.destination_tag])throw Error('Mapping CSV contains an unknown tag');const m={source:a[r.source_tag],destination:b[r.destination_tag],scale:Number(r.scale||1),offset:Number(r.offset||0)};for(const k of ['minimum','maximum'])if(r[k]!==undefined&&r[k]!=='')m[k]=Number(r[k]);return m});draw()});draw()}
function parseCSV(text,delimiter=','){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===delimiter&&!quoted){row.push(cell);cell=''}else if(c==='\n'&&!quoted){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell=''}else cell+=c}if(cell||row.length){row.push(cell.replace(/\r$/,''));rows.push(row)}if(!rows.length)return [];const headers=rows.shift().map(v=>v.replace(/^\ufeff/,''));return rows.filter(r=>r.some(v=>v!=='')).map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]||''])))}
async function loadSample(name){ensureEditable();if(dirty&&!confirm('Replace unsaved configuration with this sample?'))return;const r=await fetch('/examples/'+name);if(!r.ok)throw Error('Sample file unavailable');project=await r.json();await save();page='dashboard';render();toast('Sample loaded. All jobs are stopped.')}
async function browse(){const c=currentConnection();ensureEditable(c);toast('Browsing server…');const r=await api('connection','POST',{connection:c,mode:'browse'});let chosen=new Set();modal('Browse OPC UA server',`<p>${r.tags.length} variables found. Filter and add the required points.</p><input id="browse-filter" placeholder="Filter tag names"><div id="browse-list" style="max-height:380px;overflow:auto;margin-top:15px"></div><p id="browse-count" class="hint"></p>`,async()=>{for(const nid of chosen){const t=r.tags.find(t=>t.nodeid===nid);if(!c.tags.some(x=>x.nodeid===nid||x.tag===t.tag))c.tags.push({id:id(),index:c.tags.length+1,tag:t.tag,nodeid:nid,dtype:'Float'})}changed();const resolved=await api('resolve','POST',{connection:c});c.tags=resolved.tags;toast(`${chosen.size} selected; datatypes resolved`)},'Add selected');const draw=()=>{const match=r.tags.filter(t=>t.tag.toLowerCase().includes($('browse-filter').value.toLowerCase()));$('browse-list').innerHTML=match.slice(0,200).map(t=>`<label class="checkbox"><input type="checkbox" data-node="${esc(t.nodeid)}" ${chosen.has(t.nodeid)?'checked':''}><span>${esc(t.tag)}<br><small>${esc(t.nodeid)}</small></span></label>`).join('');$('browse-count').textContent=`${match.length} matching variables · First 200 shown · ${chosen.size} selected`;document.querySelectorAll('[data-node]').forEach(x=>x.onchange=()=>{if(x.checked)chosen.add(x.dataset.node);else chosen.delete(x.dataset.node);$('browse-count').textContent=`${match.length} matching variables · ${chosen.size} selected`})};$('browse-filter').oninput=draw;draw()}
function viewJob(j){const s=snapshot.jobs[j.id]||{state:'STOPPED',values:[]};modal(j.name+' · Live values',`<div id="live-job-state">${stateBadge(s.state)}</div><p class="hint">First 100 points are shown. Use tag search and Read visible values to inspect other points.</p><div class="table-wrap"><table><thead><tr><th>Tag</th><th>Value</th><th>Datatype</th><th>Raw registers (hex)</th></tr></thead><tbody id="live-job-values"></tbody></table></div>`,async()=>{},'Close');$('modal').dataset.liveJob=j.id;updateLiveJob()}
function updateLiveJob(){const ident=$('modal').dataset.liveJob;if(!$('modal').open||!ident||!$('live-job-values'))return;const s=snapshot.jobs[ident]||{state:'STOPPED',values:[]};$('live-job-state').innerHTML=stateBadge(s.state)+` <span class="hint">${s.age??'—'}s since last update · ${s.cycles||0} cycles</span>`;$('live-job-values').innerHTML=(s.values||[]).map(t=>`<tr><td class="code">${esc(t.tag)}</td><td class="mono">${esc(t.value)} ${esc(t.units||'')}</td><td>${esc(t.dtype)}</td><td class="mono">${t.raw?t.raw.map(v=>'0x'+Number(v).toString(16).toUpperCase().padStart(4,'0')).join(' '):'—'}</td></tr>`).join('')}
function bind(){if($('register-format'))$('register-format').onchange=e=>{registerFormat=e.target.value};document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async e=>{e.preventDefault();try{await handle(b.dataset.action,b.dataset.id,b)}catch(e){toast(e.message,true)}});if($('connection-select'))$('connection-select').onchange=e=>{selectedConnection=e.target.value;tagPage=0;search='';render()};if($('tag-search'))$('tag-search').oninput=e=>{search=e.target.value;tagPage=0;const pos=e.target.selectionStart;render();$('tag-search').focus();$('tag-search').setSelectionRange(pos,pos)}}
async function handle(action,ident,button){const c=currentConnection(),j=project.jobs.find(j=>j.id===ident);switch(action){case 'new-connection':connectionForm();break;case 'edit-connection':connectionForm(project.connections.find(c=>c.id===ident));break;case 'test':{button.disabled=true;try{await api('connection','POST',{connection:project.connections.find(c=>c.id===ident),mode:'test'});toast('Connection successful')}finally{button.disabled=false}break}case 'delete-connection':ensureEditable(project.connections.find(c=>c.id===ident));if(project.jobs.some(j=>j.connection===ident||j.source===ident))throw Error('Delete jobs using this connection first');if(confirm('Delete this connection and its tags?')){project.connections=project.connections.filter(c=>c.id!==ident);changed();render()}break;case 'connection-tags':selectedConnection=ident;page='tags';search='';tagPage=0;render();break;case 'import-tags':ensureEditable(c);pick('.db,.csv',async f=>{const r=await api('import-tags','POST',{filename:f.name,text:await f.text()});if(c.tags.length&&!confirm('Replace this connection’s existing tags? Existing job selections/mappings may need updating.'))return;c.tags=r.tags;if(c.protocol==='modbus'){let next={holding:0,input:0,coil:0,discrete:0};for(const t of c.tags){t.area=t.area||'holding';t.order=t.order||'ABCD';if(t.address===undefined)t.address=next[t.area];next[t.area]=Number(t.address)+(['coil','discrete'].includes(t.area)?1:registerWidth(t.dtype))}}changed();render();toast(`${r.tags.length} exact tags imported. Resolve OPC UA metadata before starting.`)});break;case 'tag-table':tagTable(c);break;case 'undo-tag-table':undoTagEdit(c);break;case 'mixed-tags':mixedTagForm(c);break;case 'simulation-groups':await simulationGroups(c);break;case 'generate-tags':generateTagForm(c);break;case 'bulk-registers':bulkRegisters(c);break;case 'add-tag':tagForm();break;case 'edit-tag':tagForm(c.tags.find(t=>t.id===ident));break;case 'delete-tag':ensureEditable(c);if(project.jobs.some(j=>(j.tags||[]).includes(ident)||(j.mappings||[]).some(m=>m.source===ident||m.destination===ident)))throw Error('Remove this tag from job selections/mappings first');c.tags=c.tags.filter(t=>t.id!==ident);changed();render();break;case 'browse':await browse();break;case 'resolve':ensureEditable(c);button.disabled=true;toast('Resolving NodeIds and live datatypes…');try{const r=await api('resolve','POST',{connection:c});c.tags=r.tags;if(c.protocol==='modbus'){let next={holding:0,input:0,coil:0,discrete:0};for(const t of c.tags){t.area=t.area||'holding';t.order=t.order||'ABCD';if(t.address===undefined)t.address=next[t.area];next[t.area]=Number(t.address)+(['coil','discrete'].includes(t.area)?1:registerWidth(t.dtype))}}changed();render();toast(`${r.tags.length} tags resolved. Save project to keep the mapping.`)}finally{button.disabled=false}break;case 'prev-tags':tagPage--;render();break;case 'next-tags':tagPage++;render();break;case 'export-tags':{const headers=['tag','dtype','nodeid','browse_name','address','area','order'];const quote=v=>'"'+String(v??'').replaceAll('"','""')+'"';download('tags.csv',headers.join(',')+'\n'+c.tags.map(t=>headers.map(h=>quote(t[h])).join(',')).join('\n'),'text/csv');break}case 'read-tags':{const visible=c.tags.filter(t=>t.tag.toLowerCase().includes(search.toLowerCase())).slice(tagPage*50,(tagPage+1)*50);button.disabled=true;try{const r=await api('connection','POST',{connection:{...c,tags:visible},mode:'read'});for(const t of visible){const raw=r.raw?.[t.id];$('value-'+t.id).textContent=registerFormat==='decimal'||!raw?r.values[t.id]:raw.map(v=>registerFormat==='hex'?'0x'+Number(v).toString(16).toUpperCase().padStart(4,'0'):Number(v).toString(2).padStart(16,'0')).join(' ')}}finally{button.disabled=false}break}case 'write-tag':{const t=c.tags.find(t=>t.id===ident);modal('Write '+t.tag,`${input('manual-value','Value','','text')}<div class="notice">This writes one value to ${esc(c.name)}. Check the destination before applying.</div>`,async()=>{const raw=$('manual-value').value;const value=t.dtype==='Boolean'?(['true','1'].includes(raw.toLowerCase())?true:['false','0'].includes(raw.toLowerCase())?false:(()=>{throw Error('Boolean values must be true, false, 0, or 1')})()):['Int64','UInt64','String','DateTime'].includes(t.dtype)?raw:Number(raw);if(raw.trim()==='')throw Error('Enter a value');await api('connection','POST',{connection:{...c,tags:[t]},mode:'write',values:{[t.id]:value}});toast('Value written successfully')},'Write value');break}case 'new-job':jobForm();break;case 'edit-job':jobForm(j);break;case 'delete-job':ensureEditable(j);if(confirm('Delete this job?')){project.jobs=project.jobs.filter(j=>j.id!==ident);changed();render()}break;case 'start':if(dirty)throw Error('Save the project before starting a job');await api('action','POST',{action:'start',id:ident});await poll();break;case 'pause':case 'resume':await api('action','POST',{action,id:ident});await poll();break;case 'stop':await api('action','POST',{action:'stop',id:ident});await poll();break;case 'start-all':if(dirty)throw Error('Save the project before starting');await api('action','POST',{action:'start_all'});await poll();break;case 'view-job':viewJob(j);break;case 'mapping-job':mappingForm(j);break;case 'load-demo':await loadSample('Local_Modbus_Demo.json');break;case 'load-opcua-demo':if(project.connections.length&&!confirm('Replace the workspace with the local OPC UA demo (1,000 dynamic REAL points)? Export your current project first if needed. Jobs load stopped.'))return;await loadSample('Local_1000_OPCUA_Project.json');break;case 'apply-settings':ensureEditable();project.name=$('project-title').value;project.settings={...project.settings,autostart:$('auto-jobs').checked};changed();await save();break;case 'export-project':{const p=structuredClone(project);for(const c of p.connections)delete c.password;download('protocol-project.json',JSON.stringify(p,null,2));toast('Exported without passwords');break}case 'import-project':ensureEditable();pick('.json',async f=>{const p=JSON.parse(await f.text());await api('project','PUT',p);project=p;dirty=false;$('dirty').classList.add('hidden');render();toast('Project imported; jobs are stopped')});break;case 'new-project':ensureEditable();if(confirm('Replace this workspace with an empty project? Export it first if needed.')){project={version:1,name:'My protocol project',connections:[],jobs:[],settings:{autostart:false}};await save();render()}break;case 'apply-json':ensureEditable();{const p=JSON.parse($('project-json').value);await api('project','PUT',p);project=p;dirty=false;$('dirty').classList.add('hidden');render();toast('Project validated and saved')}break;case 'diagnostics':{button.disabled=true;try{const r=await api('diagnostics','POST',{});modal('Local installation check',`<div class="notice">${esc(r.ok?r.message:r.error)}</div><ul>${r.checks.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`,async()=>{},'Close')}finally{button.disabled=false}break}case 'startup-on':case 'startup-off':{const r=await api('startup','POST',{enabled:action==='startup-on'});toast(r.message);break}case 'shutdown':if(confirm('Stop all jobs and exit the background application?')){await api('shutdown','POST',{});$('content').innerHTML='<div class="empty"><h2>Application stopped</h2><p>Use Open App to start it again.</p></div>';clearInterval(pollTimer)}break;case 'export-log':download('activity.json',JSON.stringify(snapshot.logs,null,2));break;}}
async function poll(){try{snapshot=await api('status');retryRecovery();await refreshScenarios();$('service').textContent='● Local application connected';$('service').style.color='#147252';if(['dashboard','jobs','logs','scenarios','runs','bridges'].includes(page)&&!$('modal').open)render();updateLiveJob();if(page==='inspector')await refreshInspector();if(page==='verification')await refreshVerification();if(page==='data-verification')await refreshDataVerification();if(page==='health')await refreshHealth();if(page==='performance')await refreshPerformance();if(page==='bridges')await refreshBridges();recoveryStatus();const failures=Object.values(snapshot.jobs).filter(s=>['ERROR','RECONNECTING','OVERRUN','WAITING_RECOVERY','RETRY_EXHAUSTED'].includes(s.state));$('banner').classList.toggle('hidden',!failures.length);$('banner').textContent=`${failures.length} job(s) need attention. Open Activity or the job card for details.`}catch(e){$('service').textContent='Local application disconnected';$('service').style.color='#bc3e38'}}
let pollTimer;
$('cancel-modal').onclick=()=>{$('modal').close();delete $('modal').dataset.liveJob};$('modal').addEventListener('close',()=>{delete $('modal').dataset.liveJob;if(!$('modal').open)resetRecoveryForm()});
$('save').onclick=()=>save().catch(e=>toast(e.message,true));$('stop-all').onclick=async()=>{try{await api('action','POST',{action:'stop_all'});await poll();toast('All jobs stopped')}catch(e){toast(e.message,true)}};
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{page=b.dataset.page;render()});
(async()=>{try{const init=await api('bootstrap');token=init.token;window.workbenchRole=init.user?.role;if(init.authentication_required){securityLogin();return}if(init.licence_ack_required){await licenceNotice();return}loginStartupAvailable=init.login_startup_available===true;recoveryDataDirectory=init.data_directory;project=await api('project');const preference=await api('project-library/preferences');page=preference.landing_page;document.body.dataset.density=preference.density;await initializeRecovery();await loadLicenceStatus();await poll();render();pollTimer=setInterval(poll,2000)}catch(e){toast(e.message,true)}})();

function tagSelection(connection){
 const tags=connection.tags||[];if(!tags.length){toast('Add tags to this connection first',true);return}
 const existing=$('j-tags').value.split(',').map(x=>x.trim()).filter(Boolean);
 let selected=new Set(existing.length?existing:tags.map(t=>t.id));let offset=0;
 const chooser=document.createElement('dialog');chooser.innerHTML=`<h2>Choose job tags</h2><p class="hint">Filter and check individual points. Matching simulation jobs should use the same pairing indices.</p><input id="selection-filter" placeholder="Filter tag names"><div class="actions" style="margin:12px 0"><button type="button" id="selection-all" class="small secondary">Select all tags</button><button type="button" id="selection-matching" class="small secondary">Select filtered tags</button><button type="button" id="selection-clear" class="small secondary">Clear selection</button></div><div id="selection-list" style="max-height:340px;overflow:auto"></div><div class="pagination"><span id="selection-count"></span><button id="selection-prev" class="small secondary">Previous</button><button id="selection-next" class="small secondary">Next</button></div><div class="dialog-actions"><button id="selection-cancel" class="secondary">Cancel</button><button id="selection-apply">Apply selection</button></div>`;
 document.body.appendChild(chooser);const q=x=>chooser.querySelector('#'+x);
 const matches=()=>tags.filter(t=>t.tag.toLowerCase().includes(q('selection-filter').value.toLowerCase()));
 const draw=()=>{const filtered=matches();offset=Math.min(offset,Math.max(0,Math.ceil(filtered.length/100)-1));q('selection-list').innerHTML=filtered.slice(offset*100,(offset+1)*100).map(t=>`<label class="checkbox"><input type="checkbox" data-selected-tag="${t.id}" ${selected.has(t.id)?'checked':''}>${esc(t.tag)} <small>${esc(t.dtype)}</small></label>`).join('');q('selection-count').textContent=`${selected.size} selected · ${filtered.length} matches · Page ${offset+1}`;q('selection-prev').disabled=offset===0;q('selection-next').disabled=(offset+1)*100>=filtered.length;q('selection-apply').disabled=selected.size===0;chooser.querySelectorAll('[data-selected-tag]').forEach(x=>x.onchange=()=>{if(x.checked)selected.add(x.dataset.selectedTag);else selected.delete(x.dataset.selectedTag);q('selection-count').textContent=`${selected.size} selected · ${filtered.length} matches`;q('selection-apply').disabled=selected.size===0})};
 q('selection-filter').oninput=()=>{offset=0;draw()};q('selection-all').onclick=()=>{selected=new Set(tags.map(t=>t.id));draw()};q('selection-matching').onclick=()=>{for(const t of matches())selected.add(t.id);draw()};q('selection-clear').onclick=()=>{selected.clear();draw()};q('selection-prev').onclick=()=>{offset--;draw()};q('selection-next').onclick=()=>{offset++;draw()};q('selection-cancel').onclick=()=>chooser.close();q('selection-apply').onclick=()=>{$('j-tags').value=selected.size===tags.length?'':tags.filter(t=>selected.has(t.id)).map(t=>t.id).join(',');chooser.close();toast('Tag selection updated')};chooser.onclose=()=>chooser.remove();chooser.showModal();draw();
}

function registerWidth(kind){return ['Double','Int64','UInt64'].includes(kind)?4:['Float','Int32','UInt32'].includes(kind)?2:1}
function bulkRegisters(connection){
 ensureEditable(connection);if(!connection.tags.length)throw Error('Import or add tags first');
 modal('Bulk register setup',`<p>Configure all ${connection.tags.length.toLocaleString()} points on ${esc(connection.name)}.</p><div class="form-grid">${select('bulk-type','Datatype',['Keep each tag type',...typesFor(connection)],'Keep each tag type')}${select('bulk-area','Area',['holding','input','coil','discrete'],'holding')}${select('bulk-order','Byte / word order',['ABCD','BADC','CDAB','DCBA'],'ABCD')}${input('bulk-start','Starting protocol offset',0,'number','min="0" max="65535"')}</div><div class="notice">Addresses will be assigned sequentially, with enough words for each value. Names, IDs, and simulation pairing indices stay unchanged. Coils/discrete inputs require Boolean.</div>`,async()=>{const kind=$('bulk-type').value,area=$('bulk-area').value,order=$('bulk-order').value;let address=Number($('bulk-start').value);if(!Number.isInteger(address)||address<0)throw Error('Starting offset must be a nonnegative integer');const updated=connection.tags.map(t=>{const dt=kind==='Keep each tag type'?t.dtype:kind;if(['coil','discrete'].includes(area)&&dt!=='Boolean')throw Error('Select Boolean for coils or discrete inputs');const item={...t,dtype:dt,area,order,address};address+=['coil','discrete'].includes(area)?1:registerWidth(dt);return item});if(address>65536)throw Error('Register allocation exceeds the 65536-address space');connection.tags=updated;changed();toast(`${updated.length} points allocated. Save project to keep the configuration.`)})
}
